MonarchSectionCard({{dangerZone.heading}}, description: {{dangerZone.description}}, tone: .danger) {
    VStack(alignment: .leading, spacing: theme.spacing.space1) {
        Text({{dangerZone.title}}).monarchTextStyle(.bodyStrong)
        Text({{dangerZone.itemDescription}})
            .monarchTextStyle(.caption)
            .foregroundStyle(theme.colors.textMuted)
        MonarchButton({{dangerZone.action}}, variant: .danger) { isOpen = true }
    }
}
.sheet(isPresented: $isOpen) {
    NavigationStack {
        if isDone {
            MonarchEmptyState(
                "Workspace deleted",
                message: "{{flow.workspaceName|raw}} and everything in it has been deleted.",
                systemImage: "checkmark.circle",
                kind: .success,
                actionTitle: "Close",
                action: { isOpen = false }
            )
        } else {
            impact
        }
    }
    .interactiveDismissDisabled(isDeleting)
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = false
@State private var typed = ""
@State private var isMatched = false
@State private var isVerifying = false
@State private var isDeleting = false
@State private var isDone = false
@State private var failure: String?

private var impact: some View {
    ScrollView {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                Text("Step 1 of 4").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                ProgressView(value: 0.25).progressViewStyle(.monarchLinear)
            }
            Text({{flow.intro}}).monarchTextStyle(.body)
            MonarchConsequenceList(
                [
                    MonarchConsequence(.removed, {{impactLabels.apps}}, count: {{impact.apps}}),
                    MonarchConsequence(.removed, {{impactLabels.records}}, count: {{impact.records}}),
                    MonarchConsequence(.changed, {{impactLabels.members}}, count: {{impact.members}}),
                    MonarchConsequence(.changed, {{impactLabels.subscriptions}}, count: {{impact.subscriptions}}),
                    MonarchConsequence(.changed, {{impactLabels.domains}}, count: {{impact.domains}}),
                ],
                heading: {{flow.heading}},
                isGrouped: true
            )
            HStack {
                MonarchButton({{flow.cancel}}) { isOpen = false }
                NavigationLink({{flow.continue}}, value: "confirm")
                    .buttonStyle(.monarch(.primary, fullWidth: true))
            }
        }
        .padding(theme.spacing.space6)
    }
    .navigationTitle({{flow.title}})
    .navigationDestination(for: String.self) { _ in confirm }
}

private var confirm: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space4) {
        Text("This cannot be undone.").monarchTextStyle(.body)
        MonarchTypeToConfirmInput(phrase: {{flow.workspaceName}}, text: $typed, onMatchChange: { isMatched = $0 })
        if let failure {
            MonarchInlineNotice(failure, tone: .danger)
        }
        MonarchButton({{dangerZone.action}}, variant: .danger, isLoading: isDeleting, fullWidth: true) {
            isVerifying = true
        }
        .disabled(!isMatched)
    }
    .padding(theme.spacing.space6)
    .navigationTitle("Confirm deletion")
    .sheet(isPresented: $isVerifying) {
        MonarchStepUpAuthDialog(
            description: "Deleting a workspace needs you to confirm your identity.",
            onVerified: { delete() },
            onVerify: { _ in
                // The app re-authenticates the person here.
            }
        )
    }
}

private func delete() {
    isDeleting = true
    failure = nil
    Task {
        do {
            // The app deletes the workspace here.
            try await Task.sleep(for: .milliseconds(300))
            isDone = true
        } catch {
            failure = "The workspace couldn’t be deleted. Try again."
        }
        isDeleting = false
    }
}

